    "pub_date": "2026-11-02 21:23:55",
    "author": "",
    "description": "如果有人从外地去你家做客，她临走的时候，你会不会给她带一些当地的特色小吃？ 满满的礼品盒里装着满满的亲情，拎在两只手里沉甸甸的，放在心里暖暖的，甜甜的。分别的那一瞬间，她哽咽着说不出话。这一别，山高水远，不知何时才能相见，珍重。 她拎着一箱子大闸蟹、两只很大很肥的烤鸭、一大袋子干果饼干瓜子坐地铁、出地铁站、慌慌张张进高铁站，去宽阔的候车大厅找检票口。天热，她穿了高领厚毛衣、外套，满头大汗。她一直在跑，怕错过上车时间。跑到检票口，她一看时…",
    "content": "如果有人从外地去你家做客，她临走的时候，你会不会给她带一些当地的特色小吃？ 满满的礼品盒里装着满满的亲情，拎在两只手里沉甸甸的，放在心里暖暖的，甜甜的。分别的那一瞬间，她哽咽着说不出话。这一别，山高水远，不知何时才能相见，珍重。 她拎着一箱子大闸蟹、两只很大很肥的烤鸭、一大袋子干果饼干瓜子坐地铁、出地铁站、慌慌张张进高铁站，去宽阔的候车大厅找检票口。天热，她穿了高领厚毛衣、外套，满头大汗。她一直在跑，怕错过上车时间。跑到检票口，她一看时间，距离检票时间，提前二十分钟。她从十一点四十从你家出发，用了一个小时左右的时间…"
