    "title": "瞰中国丨内蒙古：机械化作业奏响秋收乐章",
    "link": "http://www.news.cn/20261102/780bd8fbabae4bf7b699d424d08f41f5/c.html",
    "pub_date": "2026-11-02 21:21:39",
    "author": "",
    "description": "深秋时节，内蒙古自治区达拉特旗王爱召镇小淖村的万亩高粱田迎来收割季。连片高粱穗大粒满，染红田野。多台大型联合收割机穿梭其间，收割、脱粒、装仓一气呵成；收割机与运粮车协同配合，新粮随收随运，田间机声轰鸣，奏响一曲秋日丰收乐章。 当地高粱实行成片种植、统一管理、机械化收获的生产模式，现代化农机的投入使用，为秋收工作按下“加速键”，大幅提升粮食采收效率，切实保障秋收进度、守护粮食安全。 制片人：马宝军 策划：李琳 杜屹然 责编：王家辉 编导：…",
    "content": "深秋时节，内蒙古自治区达拉特旗王爱召镇小淖村的万亩高粱田迎来收割季。连片高粱穗大粒满，染红田野。多台大型联合收割机穿梭其间，收割、脱粒、装仓一气呵成；收割机与运粮车协同配合，新粮随收随运，田间机声轰鸣，奏响一曲秋日丰收乐章。 当地高粱实行成片种植、统一管理、机械化收获的生产模式，现代化农机的投入使用，为秋收工作按下“加速键”，大幅提升粮食采收效率，切实保障秋收进度、守护粮食安全。 制片人：马宝军 策划：李琳 杜屹然 责编：王家辉 编导：陶玲君 报道员：李慧龙 杨耀中 新媒体编辑：杜利伟 供稿来源：达拉特旗融媒体中心…"
