    "content": "KB5127936 预览更新的发布说明显示，微软已修复了 2026 年 9 月安全更新在 Windows 11 上导致的始终启用 VPN 连接故障。该修复现已面向安装 Windows 11 25H2 和 26H2 可选 10 月预览更新的设备提供。跳过该更新的设备将继续受到影响，直到补丁星期二累积更新。 微软在 9 月下旬发给 IT 管理员的服务警报中首次承认了该问题。根据该警报，当始终启用 VPN 配置文件使用 IKEv2 和 SSTP 的自动协议选择时，故障在 9 月安全更新后影响了 Windows 11 系统…"
