    "description": "新华社北京11月2日电（记者刘慧）中国证监会11月2日表示，将抓紧修订《上市公司股份回购规则》，增强护盘式回购的约束力。规则正式修订前，证监会将加大和有关方面协调配合，支持、鼓励和督促具备条件的上市公司，特别是重要指数成份股公司、龙头科技股公司按照相关要求结合自身实际积极实施股份回购，持续做好市值管理。 中国证监会宣布，拟对维护公司价值及股东权益所必需而回购股份（护盘式回购）做四点调整优化。 一是新增股价“破发”作为可以开展护盘式回购的…",
    "content": "新华社北京11月2日电（记者刘慧）中国证监会11月2日表示，将抓紧修订《上市公司股份回购规则》，增强护盘式回购的约束力。规则正式修订前，证监会将加大和有关方面协调配合，支持、鼓励和督促具备条件的上市公司，特别是重要指数成份股公司、龙头科技股公司按照相关要求结合自身实际积极实施股份回购，持续做好市值管理。 中国证监会宣布，拟对维护公司价值及股东权益所必需而回购股份（护盘式回购）做四点调整优化。 一是新增股价“破发”作为可以开展护盘式回购的情形之一，规定护盘式回购不适用“公司股票上市已满六个月”的限制，取消护盘式回购中…"
