    "content": "据媒体近日报道，美国空军正在考虑为其轰炸机增加空对空作战能力的方案，作为最新版“战斗机部队结构计划”的一部分。 在此之前，美国空军曾提出最新的B-21“突袭者”可能在未来承担空对空作战任务，并与协同作战飞机（CCA）共同参与战斗。 测试中的B-21轰炸机，具备较为优异的隐身能力。 飞行的“弹药库” 武库机实则是载满导弹的大型战机，其概念最早可追溯到20世纪70年代，在B-1轰炸机项目研制期间，研发人员曾设想为B-1A轰炸机加装数十枚射程达184千米的AIM-54“不死鸟”远程空空导弹，尽管由于技术限制未能实现，但这…"
