    "description": "随着中国部分地方政府集中加快住宅用地供应，10月300城住宅用地成交规模大幅增长，带动住宅用地出让金同比增长89%。 中国房地产数据平台中指研究院数据显示，受9月部分城市加快供地、宅地供应集中放量影响，10月、出让金同比大幅增长。 据中指数据，10月300城住宅用地成交规划建面10820万平方米，同比增长91.8%；出让金3756亿元（人民币，721.4亿新元），同比增长89.0%。 报告指出，成交放量主要受供应端带动，在去库存相关政策…",
    "content": "随着中国部分地方政府集中加快住宅用地供应，10月300城住宅用地成交规模大幅增长，带动住宅用地出让金同比增长89%。 中国房地产数据平台中指研究院数据显示，受9月部分城市加快供地、宅地供应集中放量影响，10月、出让金同比大幅增长。 据中指数据，10月300城住宅用地成交规划建面10820万平方米，同比增长91.8%；出让金3756亿元（人民币，721.4亿新元），同比增长89.0%。 报告指出，成交放量主要受供应端带动，在去库存相关政策执行节点影响下，9月部分城市加快供地节奏，300城宅地推出规划建面同比增长106…"
