    "description": "新华社北京11月2日电（记者吴雨、任军）11月2日，中国人民银行会同金融监管总局、中国证监会等部门召开支持资本市场两项工具的座谈会，研究部署用好用足政策工具有关工作，进一步优化政策要素和实施细则，支持资本市场健康稳定发展。 2024年10月中国人民银行创设了支持资本市场的两项工具：证券、基金、保险公司互换便利（SFISF）和股票回购增持再贷款。会议认为，两项工具的市场内在稳定机制作用逐步显现，行业机构稳市和上市公司市值管理的意识、能力持…",
    "content": "新华社北京11月2日电（记者吴雨、任军）11月2日，中国人民银行会同金融监管总局、中国证监会等部门召开支持资本市场两项工具的座谈会，研究部署用好用足政策工具有关工作，进一步优化政策要素和实施细则，支持资本市场健康稳定发展。 2024年10月中国人民银行创设了支持资本市场的两项工具：证券、基金、保险公司互换便利（SFISF）和股票回购增持再贷款。会议认为，两项工具的市场内在稳定机制作用逐步显现，行业机构稳市和上市公司市值管理的意识、能力持续提升。 据介绍，为维护资本市场稳定，提升市场韧性和信心，中国人民银行、金融监管…"
