    "description": "新华社台北11月2日电（记者马欣然、李寒芳）第十七届大陆古籍艺术类图书展暨青少年国学经典诵读活动2日在台北与台中同步启幕。天龙书店台北店与台中店作为主要展区，迎来了众多爱书人与文化学者。 本届书展由上海书刊发行行业协会策划，上海香港三联书店有限公司携手台湾天龙文创出版事业有限公司共同主办。展览重点呈现《孟子》《百家姓》《三字经》等精装版古籍图书，并集中展示了涵盖人工智能版权治理、法律阐释及区域治理研究等多个前沿领域的学术著作，旨在进一步…",
    "content": "新华社台北11月2日电（记者马欣然、李寒芳）第十七届大陆古籍艺术类图书展暨青少年国学经典诵读活动2日在台北与台中同步启幕。天龙书店台北店与台中店作为主要展区，迎来了众多爱书人与文化学者。 本届书展由上海书刊发行行业协会策划，上海香港三联书店有限公司携手台湾天龙文创出版事业有限公司共同主办。展览重点呈现《孟子》《百家姓》《三字经》等精装版古籍图书，并集中展示了涵盖人工智能版权治理、法律阐释及区域治理研究等多个前沿领域的学术著作，旨在进一步深化两岸出版业的深度交流，共同拓展华文出版市场的广度与深度。 活动期间，主办方特…"
