    "description": "36氪获悉，中国证监会有关部门负责人就近期稳市场稳预期相关工作答记者问。提高上市公司股票回购增持专项再贷款覆盖率。证监会将引导推出更多权重指数公司、龙头科技股等具有较强市场影响的标志性案例。同时，督促已披露回购增持贷款计划的上市公司加快实施进度，已经申请贷款的公司加大回购实施力度，延续当前贷款回购增持的良好势头，为资本市场稳定积极贡献力量。",
    "content": "36氪获悉，中国证监会有关部门负责人就近期稳市场稳预期相关工作答记者问。提高上市公司股票回购增持专项再贷款覆盖率。证监会将引导推出更多权重指数公司、龙头科技股等具有较强市场影响的标志性案例。同时，督促已披露回购增持贷款计划的上市公司加快实施进度，已经申请贷款的公司加大回购实施力度，延续当前贷款回购增持的良好势头，为资本市场稳定积极贡献力量。"
