    "content": "中国三大金融监管部门进一步加大对资本市场的支持力度，将股票回购增持再贷款利率从1.25%下调至1%，以降低上市公司回购及股东增持股票的融资成本。 中国人民银行星期一（11月2日）发布公告说，央行当天会同国家金融监督管理总局、中国证监会等部门，先后召开证券、基金、保险公司互换便利座谈会，以及股票回购增持再贷款座谈会，听取金融机构业务进展及意见，并研究部署进一步发挥政策工具作用，支持资本市场健康稳定发展。 会议提出，为维护资本市场稳定，提升市场韧性和信心，三大金融监管部门将继续加强政策支持，优化现有工具的政策要素和实施…"
