    "pub_date": "2026-11-02 20:13:13",
    "author": "",
    "description": "新华社北京11月2日电 中共中央政治局常委、全国政协主席王沪宁2日在京分别会见俄罗斯联邦委员会主席马特维延科，由越共中央政治局委员、中央书记处书记、中央政策战略部部长阮青毅率领的越南共产党代表团。 会见马特维延科时，王沪宁表示，在习近平主席和普京总统的战略引领下，中俄关系稳步向前发展。中方愿同俄方一道，以两国元首重要共识为根本遵循，保持战略定力，深化务实合作，推动中俄新时代全面战略协作伙伴关系迈向更高水平。中国全国政协愿同俄方加强交流互…",
    "content": "新华社北京11月2日电 中共中央政治局常委、全国政协主席王沪宁2日在京分别会见俄罗斯联邦委员会主席马特维延科，由越共中央政治局委员、中央书记处书记、中央政策战略部部长阮青毅率领的越南共产党代表团。 会见马特维延科时，王沪宁表示，在习近平主席和普京总统的战略引领下，中俄关系稳步向前发展。中方愿同俄方一道，以两国元首重要共识为根本遵循，保持战略定力，深化务实合作，推动中俄新时代全面战略协作伙伴关系迈向更高水平。中国全国政协愿同俄方加强交流互鉴，为促进两国关系发展作出贡献。 马特维延科热烈祝贺中共二十届五中全会胜利召开，…"
