    "content": "（北京/布鲁塞尔综合讯）欧美“黑色星期五”促销旺季来临前，欧盟对廉价小包裹开征处理费，叠加此前的关税、合规要求等，导致中国低价小商品跨境卖家经营压力增加，备货量大减。 欧盟自11月1起，在对直邮消费者的小件包裹征收每类商品三元（欧元，下同，约4.3新元）关税的基础上，再增收新费用，对包裹中每类商品征收两 欧元的处理费 。 欧盟赶在黑色星期五、网络星期一及圣诞购物旺季前实施新规，可遏制低价商品，尤其是中国跨境电商商品涌入欧洲。 这项新规让中国跨境商品卖家陷入两难：把小包裹从中国直邮到海外消费者手中，会面临高税费；若提…"
