    "title": "实景实训推动应用落地 以赛促产赋能产业发展——人形机器人与具身智能实景实训挑战赛新闻发布会在京召开",
    "link": "https://36kr.com/p/4052511128638336?f=rss",
    "pub_date": "2026-11-02 19:10:55",
    "author": "",
    "description": "11月2日，人形机器人与具身智能实景实训挑战赛新闻发布会在北京召开，发布赛事总体安排和竞赛方案，并发布赛队集结令。马鞍山市委常委、常务副市长易茂林，中国电子学会副秘书长梁靓，马鞍山市政府秘书长吴斌，马鞍山市工业和信息化局局长滕青出席发布会。 中国电子学会副秘书长梁靓发言 梁靓表示，人形机器人与具身智能技术加速演进，产业发展正在迈入规模化应用的重要窗口期，产业发展从围绕技术、供给端发力，逐渐转向“针对场景、解决问题”。行业关注的重点已从“…",
    "content": "11月2日，人形机器人与具身智能实景实训挑战赛新闻发布会在北京召开，发布赛事总体安排和竞赛方案，并发布赛队集结令。马鞍山市委常委、常务副市长易茂林，中国电子学会副秘书长梁靓，马鞍山市政府秘书长吴斌，马鞍山市工业和信息化局局长滕青出席发布会。 中国电子学会副秘书长梁靓发言 梁靓表示，人形机器人与具身智能技术加速演进，产业发展正在迈入规模化应用的重要窗口期，产业发展从围绕技术、供给端发力，逐渐转向“针对场景、解决问题”。行业关注的重点已从“舞台上跳起来、赛场上跑起来”转向“工厂里干起来、超市里用起来”。在量产与落地加速…"
